<script setup lang="ts">
import {computed,ref,shallowRef,watch,onUnmounted} from 'vue';import {useApplication} from '../../application';import type {MinutesCurrent} from '../../shared/api/minutes-saved';import type {GenerationTemplates} from '../../shared/api/minutes-generation';import {ApiError} from '../../shared/api/client';
const props=defineProps<{meetingId:string;current:MinutesCurrent;locked:boolean}>(),emit=defineEmits<{select:[revision:string];create:[];manage:[];regenerate:[];denied:[cause:unknown]}>(),app=useApplication(),templates=shallowRef<GenerationTemplates|null>(null),saved=computed(()=>{const id=props.current.observation.templateRevisionId;return id?{id,name:props.current.presentation?.selectedTemplateName??'当前模板'}:null}),error=ref(''),loading=ref(false);let controller:AbortController|null=null,epoch=0;
async function load(cursor:string|null=null){const turn=++epoch;controller?.abort();controller=new AbortController();const signal=controller.signal;loading.value=true;error.value='';try{const page=await app.minutesGeneration.templates(props.meetingId,cursor,signal);if(turn===epoch)templates.value=cursor&&templates.value?{...page,items:[...templates.value.items,...page.items]}:page;}catch(e){if(turn===epoch&&!signal.aborted){templates.value=null;if(e instanceof ApiError&&[401,403].includes(e.status))emit('denied',e);error.value=e instanceof Error?e.message:'模板暂不可用';}}finally{if(turn===epoch)loading.value=false;}}
function select(event:Event){const element=event.target as HTMLSelectElement,id=element.value;if(id==='__more'||id==='__manage')element.value=saved.value?.id??'';if(id==='__manage')emit('manage');else if(id==='__more')void load(templates.value?.nextCursor);else if(id&&templates.value?.items.some(t=>t.revisionId===id&&t.selectable))emit('select',id);}
watch(()=>[props.meetingId,app.session.current.value?.actor.enterpriseId,props.current.observation.accessRevisionToken],()=>{templates.value=null;if(app.session.current.value)void load();},{immediate:true});onUnmounted(()=>{epoch++;controller?.abort();});
defineExpose({reload:()=>load()});
</script>
<template><div class="am-template-toolbar"><label for="minutes-template">总结模板</label><select id="minutes-template" class="select" aria-label="纪要模板" :value="saved?.id??''" :disabled="locked||loading" @change="select"><option value="">{{loading?'正在读取模板':'选择纪要模板'}}</option><option v-if="saved&&!templates?.items.some(t=>t.revisionId===saved!.id)" :value="saved.id">{{saved.name}}</option><option v-for="t in templates?.items" :key="t.revisionId" :value="t.revisionId" :disabled="!t.selectable">{{t.name}}</option><option v-if="templates?.nextCursor" value="__more">更多模板…</option><option value="__manage">管理个人模板…</option></select><button class="btn" aria-label="新增模板" :disabled="locked" @click="emit('create')">新增模板</button><button class="btn primary" :disabled="locked" @click="emit('regenerate')">重新生成</button><span v-if="current.presentation?.appliedTemplateName" class="small muted">当前正文：{{current.presentation.appliedTemplateName}}<template v-if="current.presentation.selectedTemplateName!==current.presentation.appliedTemplateName"> · 已选择 {{current.presentation.selectedTemplateName}}，生成并采用后应用</template></span><span v-if="error" class="small" role="alert">{{error}}</span></div></template>
<style scoped>.am-template-toolbar{display:flex;align-items:center;gap:10px;flex-wrap:wrap;}select{max-width:230px;min-width:160px}.am-template-toolbar [role=alert]{color:#9a3412}</style>
